-- evt:call_foot
RegisterEvent(17, "Call the lift", function()
    if not (IsQBitSet(QBit(111480))) then
        evt.StatusText("The cage does not move. The Songbird is still caged.", 5)
        evt.SetDoorState(23, DoorAction.Close)
        return
    end
    evt.SetDoorState(1, DoorAction.Close)
    evt.SetDoorState(16, DoorAction.Close)
    evt.SetDoorState(23, DoorAction.Open)
    evt.PlaySoundName("xeen_lift", -2304, 1312, -1280)
    evt.StatusText("The cage rattles down the shaft.", 4)
end, "Call the lift")

-- evt:call_top
RegisterEvent(18, "Call the lift", function()
    if not (IsQBitSet(QBit(111480))) then
