-- evt:gate1
RegisterEvent(37, "Gate", function(continueStep)
    local eventId = 37
    if not (IsQBitSet(QBit(117441))) then
        if continueStep == 1 then
            XeenQuests.hook("m24.gate_open")
            SetQBit(QBit(117441))
            return
        end
        if continueStep == 2 then
            XeenQuests.hook("m24.gate_shut")
            return
        end
        if continueStep ~= nil then
            return
        end
        XeenQuests.hook("m24.gate1")
        AskChoiceWithAnswerSteps(eventId, 3, "Will you find what you came for?", {{Answer = "Yes", Step = 1}, {Answer = "No", Step = 2}})
        return
    end
    evt.SetDoorState(6, DoorAction.Trigger)
    evt.SetDoorState(7, DoorAction.Trigger)
end, "Gate")

