-- evt:ride_down
RegisterEvent(80, "Lift: down", function()
    if not (IsQBitSet(QBit(111480))) then
        evt.StatusText("The cage does not move.")
        evt.SetDoorState(41, DoorAction.Close)
        return
    end
    evt.SetDoorState(1, DoorAction.Close)
    evt.SetDoorState(16, DoorAction.Close)
    evt.SetDoorState(41, DoorAction.Open)
    evt.PlaySoundName("xeen_lift", -2304, 1312, -1280)
    evt.StatusText("The cage sinks into the dark.")
end, "Lift: down")

-- evt:ride_up
RegisterEvent(81, "Lift: up", function()
    if not (IsQBitSet(QBit(111480))) then
        evt.StatusText("The cage does not move. The Songbird is still caged.", 5)
        evt.SetDoorState(42, DoorAction.Close)
        return
    end
    evt.SetDoorState(1, DoorAction.Open)
    evt.SetDoorState(16, DoorAction.Open)
    evt.SetDoorState(42, DoorAction.Open)
    evt.PlaySoundName("xeen_lift", -2304, 1312, -1280)
    evt.StatusText("The cage climbs the long shaft to the tower.", 4)
end, "Lift: up")

